"use client";

import React, { useState, useEffect, useCallback, useMemo } from "react";
// Mock Firebase imports (assuming they are available in the environment)
import { initializeApp } from "firebase/app";
import {
  getAuth,
  signInAnonymously,
  signInWithCustomToken,
  onAuthStateChanged,
} from "firebase/auth";
import {
  getFirestore,
  doc,
  setDoc,
  getDoc,
  collection,
  setLogLevel,
} from "firebase/firestore";

// Mock Redux Toolkit imports
const configureStore = (options) => ({
  getState: () => options.reducer,
  dispatch: (action) => console.log("Redux Action:", action),
  subscribe: () => () => {},
  ...options,
});
const createSlice = ({ name, initialState, reducers }) => ({
  name,
  reducer: (state = initialState, action) => {
    const handler = reducers[action.type.replace(`${name}/`, "")];
    return handler ? handler(state, action.payload) : state;
  },
  actions: Object.fromEntries(
    Object.keys(reducers).map((key) => [
      key,
      (payload) => ({ type: `${name}/${key}`, payload }),
    ])
  ),
});

// Mock React Query (TanStack Query) imports
const {
  QueryClient,
  QueryClientProvider,
  useMutation,
  useQuery,
  useQueryClient,
} = (() => {
  const QueryClient = function () {
    this.data = {};
    this.mutations = {};
    this.setQueryData = (key, data) => {
      this.data[JSON.stringify(key)] = data;
      console.log(`Query data set for ${key}:`, data);
    };
    this.getQueryData = (key) => this.data[JSON.stringify(key)];
  };
  const QueryClientProvider = ({ client, children }) => <>{children}</>;

  const useQuery = (queryKey, queryFn, options = {}) => {
    const key = JSON.stringify(queryKey);
    const [data, setData] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
      if (!queryKey) return;
      setIsLoading(true);
      setError(null);
      queryFn()
        .then((res) => {
          setData(res);
          setIsLoading(false);
        })
        .catch((err) => {
          setError(err);
          setIsLoading(false);
        });
    }, [key, queryFn]);

    return { data, isLoading, error };
  };

  const useMutation = (mutationFn, options = {}) => {
    const [isLoading, setIsLoading] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [error, setError] = useState(null);

    const mutate = async (variables) => {
      setIsLoading(true);
      setIsSuccess(false);
      setError(null);
      try {
        const result = await mutationFn(variables);
        setIsSuccess(true);
        if (options.onSuccess) options.onSuccess(result, variables);
        return result;
      } catch (err) {
        setError(err);
        if (options.onError) options.onError(err, variables);
        return Promise.reject(err);
      } finally {
        setIsLoading(false);
      }
    };

    return { mutate, isLoading, isSuccess, error };
  };

  const useQueryClient = () => ({
    invalidateQueries: () => console.log("Queries invalidated"),
  });

  return {
    QueryClient,
    QueryClientProvider,
    useMutation,
    useQuery,
    useQueryClient,
  };
})();

// --- 1. FIREBASE & AUTH CONTEXT SETUP ---

// IMPORTANT: Replace these placeholders with your ACTUAL Firebase configuration!
const MOCK_FIREBASE_CONFIG = {
  apiKey: "YOUR_API_KEY", // Replace with your key
  authDomain: "your-project.firebaseapp.com",
  projectId: "your-project-id",
  storageBucket: "your-project-id.appspot.com",
  messagingSenderId: "1234567890",
  appId: "1:1234567890:web:abcdef123456",
};

const appId = MOCK_FIREBASE_CONFIG.appId || "default-app-id";
const initialAuthToken = null; // We'll use anonymous sign-in

const FirebaseContext = React.createContext(null);

const FirebaseProvider = ({ children }) => {
  const [firebaseReady, setFirebaseReady] = useState(false);
  const [auth, setAuth] = useState(null);
  const [db, setDb] = useState(null);
  const [userId, setUserId] = useState(null);

  // Global Firebase instances
  let app, firestore, authentication;

  useEffect(() => {
    if (!MOCK_FIREBASE_CONFIG.apiKey) {
      console.error(
        "Firebase config not set! Replace MOCK_FIREBASE_CONFIG values."
      );
      return;
    }

    try {
      setLogLevel("debug");
      app = initializeApp(MOCK_FIREBASE_CONFIG);
      firestore = getFirestore(app);
      authentication = getAuth(app);

      setDb(firestore);
      setAuth(authentication);

      const unsubscribe = onAuthStateChanged(authentication, async (user) => {
        if (user) {
          setUserId(user.uid);
          setFirebaseReady(true);
        } else {
          // Sign in anonymously if no user is present
          if (initialAuthToken) {
            await signInWithCustomToken(authentication, initialAuthToken);
          } else {
            const anonUser = await signInAnonymously(authentication);
            setUserId(anonUser.user.uid);
          }
          setFirebaseReady(true);
        }
      });

      return () => unsubscribe();
    } catch (error) {
      console.error("Firebase Initialization Error:", error);
    }
  }, []);

  const value = { db, auth, userId, firebaseReady, appId };

  return (
    <FirebaseContext.Provider value={value}>
      {children}
    </FirebaseContext.Provider>
  );
};

// Custom hook to use Firebase context
const useFirebase = () => React.useContext(FirebaseContext);

// --- 2. REDUX SLICE FOR UI STATE (NOTIFICATIONS) ---

const notificationSlice = createSlice({
  name: "notification",
  initialState: { message: "", type: "info" },
  reducers: {
    showNotification: (state, payload) => {
      state.message = payload.message;
      state.type = payload.type;
    },
    clearNotification: (state) => {
      state.message = "";
      state.type = "info";
    },
  },
});

const { showNotification, clearNotification } = notificationSlice.actions;

// Mock Redux Store
const store = configureStore({
  reducer: {
    notification: notificationSlice.reducer,
  },
  // We'll use a local mock state and context instead of true Redux context for this single file
});

const ReduxContext = React.createContext(store.getState());

const ReduxProvider = ({ children }) => {
  const [state, setState] = useState(store.getState());

  const dispatch = useCallback(
    (action) => {
      const nextState = { ...state };
      for (const key in nextState) {
        if (store.reducer[key]) {
          // Simplified state mutation logic for mock store
          const sliceName = notificationSlice.name;
          if (action.type.startsWith(`${sliceName}/`)) {
            nextState[sliceName] = store.reducer[sliceName](
              nextState[sliceName],
              action
            );
          }
        }
      }
      setState(nextState);
    },
    [state]
  );

  const value = useMemo(
    () => ({ state, dispatch, showNotification, clearNotification }),
    [state, dispatch]
  );

  return (
    <ReduxContext.Provider value={value}>{children}</ReduxContext.Provider>
  );
};

// Custom hook to use Redux context
const useRedux = () => React.useContext(ReduxContext);

// --- 3. UI COMPONENTS ---

const Notification = () => {
  const { state, dispatch, clearNotification } = useRedux();
  const { message, type } = state.notification;

  if (!message) return null;

  const colorMap = {
    success: "bg-green-100 text-green-800 border-green-400",
    error: "bg-red-100 text-red-800 border-red-400",
    info: "bg-blue-100 text-blue-800 border-blue-400",
  };

  useEffect(() => {
    if (message) {
      const timer = setTimeout(() => dispatch(clearNotification()), 5000);
      return () => clearTimeout(timer);
    }
  }, [message, dispatch, clearNotification]);

  return (
    <div
      className={`p-4 border-l-4 rounded-lg shadow-lg mb-6 ${colorMap[type]}`}
    >
      <p className="font-medium">{message}</p>
    </div>
  );
};

